/* ============================================================
   ARCANUM — Instrumento de leitura de Tarô (RWS)
   Bilíngue PT-BR / EN. Campos codificados "pt|en".
   ============================================================ */

const L = (s, lang) => {
  if (!s) return "";
  const p = String(s).split("|");
  return lang === "en" ? (p[1] || p[0]) : p[0];
};
const LA = (arr, lang) => (arr || []).map((s) => L(s, lang));

