const CARDS = [...MAJORS, ...WANDS, ...CUPS, ...SWORDS, ...PENTS].map((c) => ({
  ...c,
  el: c.arc === "M" ? c.el : { w:"Fogo|Fire", c:"Água|Water", s:"Ar|Air", p:"Terra|Earth" }[c.arc],
  suit: c.arc === "M" ? "Arcanos Maiores|Major Arcana"
      : { w:"Paus|Wands", c:"Copas|Cups", s:"Espadas|Swords", p:"Ouros|Pentacles" }[c.arc],
}));


const EL_KEY = (c) => L(c.el, "en"); // Fire | Water | Air | Earth

const norm = (s) => String(s || "").toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/[^a-z0-9 ]/g, "").trim();
const CARDS_BY_LEN = [...CARDS].sort((a, b) => L(b.name, "pt").length - L(a.name, "pt").length);
const matchCard = (raw) => {
  const q = norm(raw);
  if (!q) return null;
  // 1) nome exato (uso programático, ex.: comparar strings vindas de uma lista fechada)
  let hit = CARDS.find((c) => norm(L(c.name, "en")) === q || norm(L(c.name, "pt")) === q);
  if (hit) return hit;
  // 2) nome da carta mencionado dentro de um texto livre — nomes mais longos primeiro,
  //    para "Cavaleiro de Copas" não ser ofuscado por um casamento parcial menor
  hit = CARDS_BY_LEN.find((c) => q.includes(norm(L(c.name, "pt"))) || q.includes(norm(L(c.name, "en"))));
  return hit || null;
};

export { L, LA, CARDS, EL_KEY, norm, matchCard };
